<template>
  <div class="hold-transition login-page">
    <div class="login-box">
      <div class="login-logo">
        <a href="../../index2.html"><b>하우머치홈즈</b>관리자</a>
      </div>
      <!-- /.login-logo -->
      <div class="card">
        <div class="card-body login-card-body">
          <p class="login-box-msg">Sign in to start your session</p>

          <div class="input-group mb-3">
            <input
              type="text"
              class="form-control"
              placeholder="User name"
              v-model="username"
            />
            <div class="input-group-append">
              <div class="input-group-text">
                <span class="fas fa-envelope"></span>
              </div>
            </div>
          </div>
          <div class="input-group mb-3">
            <input
              type="password"
              class="form-control"
              placeholder="Password"
              v-model="password"
            />
            <div class="input-group-append">
              <div class="input-group-text">
                <span class="fas fa-lock"></span>
              </div>
            </div>
          </div>
          <div class="row">
            <div class="col-8"></div>
            <!-- /.col -->
            <div class="col-4">
              <button class="btn btn-primary btn-block" @click="btnLogin">
                Sign In
              </button>
            </div>
            <!-- /.col -->
          </div>
          <!-- /.social-auth-links -->
        </div>
        <!-- /.login-card-body -->
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "Login",
  props: {
    msg: String,
  },
  components: {},
  data() {
    return { username: "", password: "" };
  },
  mounted() {
    this.init();
  },
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.$store.commit("init");
    },
    btnLogin() {
      this.$login(this.username, this.password).then((re) => {
        if (re != false) {
          const jwtdata = this.$jwtDecode(this.$cookies.get("jwt"));
          this.$store.state.userId = jwtdata.payload.i;
          this.$store.state.userLevel = jwtdata.payload.l;

          this.clickList();
        }
      });
    },
    //라우터 코드로 이동
    clickList() {
      this.$router.push({
        name: "Main",
        // query: { name: "Query 프로그래밍 방식", age: 2 },
      });
    },
    clickParams() {
      this.$router.push({
        name: "CreateReview",
        params: { name: "Params 프로그래밍 방식", age: 2 },
      });
    },
  },
};
</script>
