<template>
  <div class="wrapper">
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>문자 메시지 발송</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row p-2">
            <div class="col-sm-6"></div>
            <div class="col-sm-6">
              <button
                type="button"
                class="btn btn-primary float-right"
                style="margin-left: 5px"
                @click="sendsms"
              >
                문자 전송
              </button>
            </div>
          </div>
          <div class="card">
            <!-- /.card-header -->
            <div class="card-body">
              <div class="row">
                <div class="col-sm-12">
                  <!-- textarea -->
                  <div class="form-group">
                    <label>문자 내용</label>
                    <textarea
                      class="form-control"
                      rows="3"
                      placeholder="90byte 이하의 내용으로 이루어진 문자로 한글은 45자 영문은 90자까지 입력 가능합니다."
                      v-model="content"
                      @input="fnChkByte"
                    ></textarea>
                  </div>
                </div>
                <div class="col-sm-12" style="text-align: right">
                  {{ totalByte }}byte
                </div>
                <div class="col-sm-12">
                  <table
                    id="example1"
                    class="
                      table table-bordered table-striped
                      dataTable
                      dtr-inline
                    "
                    aria-describedby="example1_info"
                  >
                    <thead>
                      <tr>
                        <th>Id</th>
                        <th>닉네임</th>
                        <th>전화번호</th>
                        <th>약관동의</th>
                        <th>알림동의</th>
                        <th>선택</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="user in userList"
                        v-bind:key="'iu2_' + user.Id"
                      >
                        <td>{{ user.Id }}</td>
                        <td>{{ user.Nickname }}</td>
                        <td>{{ user.Contact }}</td>
                        <td>
                          <div class="icheck-primary">
                            <input
                              type="checkbox"
                              v-model="user.Agree"
                              :id="'check1_' + user.Id"
                              disabled
                            />
                            <label for="check1"></label>
                          </div>
                        </td>
                        <td>
                          <div class="icheck-primary">
                            <input
                              type="checkbox"
                              v-model="user.IsNoti"
                              :id="'check2_' + user.Id"
                              disabled
                            />
                            <label for="check2"></label>
                          </div>
                        </td>
                        <td>
                          <div class="icheck-primary">
                            <input
                              type="checkbox"
                              :id="'check3_' + user.Id"
                              :disabled="
                                !(user.Agree && user.IsNoti) ||
                                user.Contact == null
                              "
                              :value="{ Id: user.Id, Contact: user.Contact }"
                              v-model="selectUsers"
                            />
                            <label for="check3"></label>
                          </div>
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
              <!-- <div class="row">
                <div class="col-sm-12" style="text-align: right">
                  {{ totalByte }}byte
                </div>
              </div> -->
            </div>
            <!-- /.card-body -->
          </div>
        </div>
      </section>
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";

export default {
  name: "Sms",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
  },
  data() {
    return { content: "", totalByte: 0, userList: [], selectUsers: [] };
  },
  updated() {},
  created() {
    this.getUsers();
  },
  mounted() {},
  methods: {
    getUsers() {
      this.$apiGET("/admin/sms/users").then(({ data }) => {
        this.userList = data.d;
      });
    },
    sendsms() {
      this.fnChkByte();
      if (this.totalByte == 0) {
        alert("내용을 입력 해주세요.");
        return;
      }

      if (this.totalByte <= 90) {
        if (!this.selectUsers.length) {
          alert("유저를 선택 해주세요.");
          return;
        }

        let Contacts = [];
        for (let i = 0; i < this.selectUsers.length; i++) {
          Contacts.push(this.selectUsers[i].Contact);
        }

        this.$apiPOST("/admin/sendsms", {
          Text: this.content,
          Contacts: Contacts,
        }).then((re) => {
          console.log(re);
          alert("전송 완료");
        });
      } else {
        alert("90byte 이하의 내용으로 작성해주세요.");
      }
    },
    fnChkByte() {
      //   const maxByte = 90; //최대 100바이트
      const text_val = this.content; //입력한 문자
      const text_len = text_val.length; //입력한 문자수

      let totalByte = 0;
      for (let i = 0; i < text_len; i++) {
        const each_char = text_val.charAt(i);
        const uni_char = escape(each_char); //유니코드 형식으로 변환
        if (uni_char.length > 4) {
          // 한글 : 2Byte
          totalByte += 2;
        } else {
          // 영문,숫자,특수문자 : 1Byte
          totalByte += 1;
        }
      }
      this.totalByte = totalByte;
    },
  },
};
</script>
