<template>
  <div
    class="modal fade show"
    id="modal-xl"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <SearchModal
      v-if="searchState"
      @selectedApt="selectedApt"
      @close="closeModal"
      :itemList="searchList"
    ></SearchModal>
    <div class="modal-dialog modal-xl">
      <div class="modal-content">
        <div class="modal-header">
          <template v-if="tgEditMode == 0">
            <h4 class="modal-title">리뷰 작성</h4>
          </template>
          <template v-else>
            <h4 class="modal-title">[리뷰] No : {{ tgItem.ReviewId }}</h4>
          </template>

          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <div class="card-body">
            <div class="form-group">
              <div class="row">
                <label for="seachapt">아파트 단지</label>
                <div class="col-sm-6">
                  <div class="input-group">
                    <input
                      type="search"
                      class="form-control form-control-md"
                      placeholder="검색"
                      v-model="search"
                      id="seachapt"
                    />
                    <div class="input-group-append">
                      <button
                        type="submit"
                        class="btn btn-md btn-default"
                        @click="btnSearchApartment"
                      >
                        <i class="fa fa-search"></i>
                      </button>
                    </div>
                  </div>
                </div>
                <div class="col-sm-6"></div>
              </div>
            </div>

            <div class="form-group">
              <div class="row">
                <div class="col-sm-6">
                  <label for="exampleInputEmail1">매입금액</label>
                  <select
                    class="form-control"
                    v-model="tgItem.TransactionAmount"
                  >
                    <option :value="null">선택</option>
                    <option>2억 이하</option>
                    <option>2억-4억</option>
                    <option>4억-6억</option>
                    <option>6억-8억</option>
                    <option>8억-10억</option>
                    <option>10억 이상</option>
                  </select>
                </div>
                <div class="col-sm-6">
                  <label for="exampleInputPassword1">자기자본</label>
                  <select class="form-control" v-model="tgItem.OwnAmount">
                    <option :value="null">선택</option>
                    <option>2억 이하</option>
                    <option>2억-4억</option>
                    <option>4억-6억</option>
                    <option>6억-8억</option>
                    <option>8억-10억</option>
                    <option>10억 이상</option>
                  </select>
                </div>
              </div>
            </div>

            <div class="form-group">
              <label for="exampleInputFile">리뷰내용</label>
              <textarea
                v-model="tgItem.Content"
                rows="6"
                placeholder="내용"
                class="form-control"
                id="exampleInputFile"
              />
            </div>
          </div>
        </div>
        <div class="modal-footer justify-content">
          <button
            type="button"
            class="btn btn-primary float-right"
            @click="createNoti"
          >
            저장
          </button>
          <button
            v-if="tgEditMode != 0"
            type="button"
            class="btn btn-danger float-right"
            @click="deleteNoti"
          >
            삭제
          </button>
        </div>
      </div>
      <!-- /.modal-content -->
    </div>
    <!-- /.modal-dialog -->
  </div>
</template>
<script>
import SearchModal from "../components/SearchModal.vue";
export default {
  name: "ReviewModal",
  props: { item: Object, editMode: Number },
  components: { SearchModal },
  data() {
    return {
      tgItem: null,
      tgEditMode: null,
      search: "",
      searchList: [],
      searchState: false,
    };
  },
  created() {
    this.tgEditMode = this.editMode;
    if (this.editMode == 0) {
      this.tgItem = {
        Name: "",
        Content: "",
        OwnAmount: null,
        TransactionAmount: null,
      };
    } else {
      this.tgItem = { ...this.item };
      this.search = this.tgItem.ApartmentName;
    }
  },
  mounted() {},
  methods: {
    btnSearchApartment() {
      if (this.search.length > 0) {
        this.$apiGET("/search/apt?name=" + this.search).then(({ data }) => {
          this.searchList = data.d;
          if (this.searchList.length > 0) {
            this.searchState = true;
          }
        });
      }
    },
    createNoti() {
      if (this.tgEditMode == 0) {
        this.$emit("createNotice", {
          ApartmentId: this.tgItem.ApartmentId,
          OwnAmount: this.tgItem.OwnAmount,
          TransactionAmount: this.tgItem.TransactionAmount,
          Content: this.tgItem.Content,
        });
      } else {
        this.$emit("createNotice", {
          ReviewId: this.tgItem.ReviewId,
          ApartmentId: this.tgItem.ApartmentId,
          OwnAmount: this.tgItem.OwnAmount,
          TransactionAmount: this.tgItem.TransactionAmount,
          Content: this.tgItem.Content,
        });
      }
    },
    deleteNoti() {
      this.$emit("deleteNotice", { Id: this.tgItem.ReviewId });
    },
    closeModal() {
      this.searchState = false;
    },
    selectedApt(item) {
      this.search = item.Name;
      this.tgItem.ApartmentId = item.Id;
      this.closeModal();
    },
  },
};
</script>
