<template>
  <div
    class="modal fade show"
    id="modal-default"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h4 class="modal-title">아파트 단지 검색 결과</h4>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body" style="max-height: 500px; overflow-y: auto">
          <table class="table table-bordered">
            <thead>
              <tr>
                <th style="width: 10px">Id</th>
                <th>아파트 이름</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="item in itemList" v-bind:key="'se_' + item.Id">
                <td>{{ item.Id }}</td>
                <td>
                  {{ item.Name }}
                  <button
                    type="button"
                    class="btn btn-primary float-right"
                    @click="
                      $emit('selectedApt', { Id: item.Id, Name: item.Name })
                    "
                  >
                    선택
                  </button>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  name: "SearchModal",
  props: { itemList: Array },
  components: {},
  data() {
    return {};
  },
  created() {},
  mounted() {},
  methods: {},
};
</script>
