<template>
  <div class="wrapper">
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1 v-if="pageType">차단 IP 관리(차단 리스트)</h1>
              <h1 v-else>차단 IP 관리(전체 리스트)</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-12 col-md-4">
                <button
                  v-if="pageType"
                  type="button"
                  class="btn btn-info float-left"
                  style="margin-left: 5px"
                  @click="changePage(false)"
                >
                  <i class="fas fa-sign-out-alt"></i> 전체 리스트
                </button>
                <button
                  v-else
                  type="button"
                  class="btn btn-danger float-left"
                  style="margin-left: 5px"
                  @click="changePage(true)"
                >
                  <i class="fas fa-sign-out-alt"></i> 차단 리스트
                </button>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th style="width: 50px">No</th>
                          <th>IP</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i0_' + item.Id"
                          @click="showViewModal = idx"
                        >
                          <td>{{ item.Id }}</td>
                          <td>
                            {{ item.IP }}
                            <button
                              v-if="item.IsBLocked"
                              type="button"
                              class="btn btn-danger float-right"
                              @click="sendBlock(item, false)"
                            >
                              해제
                            </button>
                            <button
                              v-else
                              type="button"
                              class="btn btn-success float-right"
                              @click="sendBlock(item, true)"
                            >
                              차단
                            </button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";

export default {
  name: "IpManagement",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
  },
  data() {
    return {
      pageType: false,
      itemList: [],
      page: 1,
      itemCount: null,
      showModal: false,
      showViewModal: null,
      selectModal: [],
      pageData: null,
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    sendBlock(tg, flag) {
      this.$apiPOST("/admin/isBlocked", { Id: tg.Id, IsBlocked: flag }).then(
        () => {
          tg.IsBLocked = flag;
        }
      );
    },
    changePage(flag) {
      this.pageType = flag;
      this.getItems(1);
    },
    getItems(pg) {
      if (this.pageType) {
        this.$apiGET("/admin/block?page=" + pg).then(({ data }) => {
          this.itemList = data.d;
          this.itemCount = data.info[0].ItemCount;
          this.page = pg;

          this.pageData = this.pageDataSetting(
            this.itemCount,
            10,
            10,
            this.page
          );
        });
      } else {
        this.$apiGET("/admin/access?page=" + pg).then(({ data }) => {
          this.itemList = data.d;
          this.itemCount = data.info[0].ItemCount;
          this.page = pg;

          this.pageData = this.pageDataSetting(
            this.itemCount,
            10,
            10,
            this.page
          );
        });
      }
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
  },
};
</script>
