<template>
  <div
    class="modal fade show"
    id="modal-xl"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog modal-xl">
      <div class="modal-content">
        <div class="modal-header">
          <h4 class="modal-title">
            [{{ item.ApartmentName }}] - {{ item.CityName }} {{ item.DvsnName }}
            {{ item.SecName }}
          </h4>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <div class="card-body">
            <div class="row">
              <div class="col-sm-6">
                <select class="form-control" v-model="OwnAmount">
                  <option :value="null">자기자본 선택</option>
                  <option>2억 이하</option>
                  <option>2억-4억</option>
                  <option>4억-6억</option>
                  <option>6억-8억</option>
                  <option>8억-10억</option>
                  <option>10억 이상</option>
                </select>
              </div>
              <div class="col-sm-6">
                <select class="form-control" v-model="TransactionAmount">
                  <option :value="null">거래금액 선택</option>
                  <option>2억 이하</option>
                  <option>2억-4억</option>
                  <option>4억-6억</option>
                  <option>6억-8억</option>
                  <option>8억-10억</option>
                  <option>10억 이상</option>
                </select>
              </div>
              <div class="col-sm-12" style="margin-top: 15px">
                <textarea
                  v-model="content"
                  placeholder="리뷰 내용"
                  class="form-control"
                  rows="5"
                />
              </div>
            </div>
          </div>
        </div>
        <div class="modal-footer justify-content">
          <button
            type="button"
            class="btn btn-primary float-right"
            @click="createNoti"
            :disabled="
              !(
                content.length > 0 &&
                OwnAmount != null &&
                TransactionAmount != null
              )
            "
          >
            작성
          </button>
        </div>
      </div>
      <!-- /.modal-content -->
    </div>
    <!-- /.modal-dialog -->
  </div>
</template>
<script>
export default {
  name: "ApartmentModal",
  props: { item: Object },
  components: {},
  data() {
    return { content: "", OwnAmount: null, TransactionAmount: null };
  },
  created() {
    // this.tgEditMode = this.editMode;
    // if (this.editMode == 0) {
    //   this.tgItem = { Title: "", Content: "" };
    // } else {
    //   this.tgItem = { ...this.item };
    // }
  },
  mounted() {
    // console.log(this.editMode);
  },
  methods: {
    createNoti() {
      this.$apiPOST("/admin/review/add", {
        ApartmentId: this.item.ApartmentId,
        OwnAmount: this.OwnAmount,
        TransactionAmount: this.TransactionAmount,
        Content: this.content,
      }).then(() => {
        this.item.ReviewCount++;
        this.$emit("close");
      });
    },
  },
};
</script>
